import{_ as l,a0 as n,w as d,s as r,I as i,x as e,a1 as t,A as o,ao as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const D=JSON.parse('{"title":"怎样在桌面上安装 Docker CE？ | LCTT x X-CMD","titleTemplate":false,"description":"怎样在桌面上安装 Docker CE？ | LCTT (201806) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"怎样在桌面上安装 Docker CE？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"怎样在桌面上安装 Docker CE？ | LCTT (201806) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201806/20180108 How to Install Docker CE on Your Desktop","title":"怎样在桌面上安装 Docker CE？","tag":"201806","desc":""},"relativePath":"201806/20180108 How to Install Docker CE on Your Desktop.md","filePath":"[post].md"}'),c={name:"201806/20180108 How to Install Docker CE on Your Desktop.md"};function k(h,s,g,u,b,f){const a=n("Link");return d(),r("div",null,[s[17]||(s[17]=i("h1",{id:"怎样在桌面上安装-docker-ce",tabindex:"-1"},[e("怎样在桌面上安装 Docker CE？ "),i("a",{class:"header-anchor",href:"#怎样在桌面上安装-docker-ce","aria-label":"Permalink to “怎样在桌面上安装 Docker CE？”"},"​")],-1)),s[18]||(s[18]=i("blockquote",null,[i("p",null,"按照这些简单的步骤在你的 Linux、Mac 或 Windows 桌面上安装 Docker CE。")],-1)),s[19]||(s[19]=i("p",null,[i("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/containers-volumes_0.jpg?itok=gv0_MXiZ",alt:""})],-1)),i("p",null,[t(a,{href:"https://www.linux.com/blog/intro-to-linux/2017/12/container-basics-terms-you-need-know"},{default:o(()=>[...s[0]||(s[0]=[e("在上一篇文章中",-1)])]),_:1}),s[1]||(s[1]=e("，我们学习了容器世界的一些基本术语。当我们运行命令并在后续文章中使用其中一些术语时，这些背景信息将会派上用场，包括这篇文章。本文将介绍在桌面 Linux、 macOS 和 Windows 上安装 Docker，它适用于想要开始使用 Docker 容器的初学者。唯一的先决条件是你对命令行界面满意。",-1))]),s[20]||(s[20]=p(`<h3 id="为什么我在本地机器上需要-docker-ce" tabindex="-1">为什么我在本地机器上需要 Docker CE？ <a class="header-anchor" href="#为什么我在本地机器上需要-docker-ce" aria-label="Permalink to “为什么我在本地机器上需要 Docker CE？”">​</a></h3><p>作为一个新用户，你很可能想知道为什么你在本地系统上需要容器。难道它们不是作为微服务在云和服务器中运行吗？尽管容器长期以来一直是 Linux 世界的一部分，但 Docker 才真正使容器的工具和技术步入使用。</p><p>Docker 容器最大的优点是可以使用本地机器进行开发和测试。你在本地系统上创建的容器映像可以在“任何位置”运行。开发人员和操作人员之间不再会为应用程序在开发系统上运行良好但生产环境中出现问题而产生纷争。</p><p>而这个关键是，要创建容器化的应用程序，你必须能够在本地系统上运行和创建容器。</p><p>你可以使用以下三个平台中的任何一个 —— 桌面 Linux、 Windows 或 macOS 作为容器的开发平台。一旦 Docker 在这些系统上成功运行，你将可以在不同的平台上使用相同的命令。因此，接下来你运行的操作系统无关紧要。</p><p>这就是 Docker 之美。</p><h3 id="让我们开始吧" tabindex="-1">让我们开始吧 <a class="header-anchor" href="#让我们开始吧" aria-label="Permalink to “让我们开始吧”">​</a></h3><p>现在有两个版本的 Docker：Docker 企业版（EE）和 Docker 社区版（CE）。我们将使用 Docker 社区版，这是一个免费的 Docker 版本，面向想要开始使用 Docker 的开发人员和爱好者。</p><p>Docker CE 有两个版本：stable 和 edge。顾名思义，stable（稳定）版本会为你提供经过充分测试的季度更新，而 edge 版本每个月都会提供新的更新。经过进一步的测试之后，这些边缘特征将被添加到稳定版本中。我建议新用户使用 stable 版本。</p><p>Docker CE 支持 macOS、 Windows 10、 Ubuntu 14.04/16.04/17.04/17.10、 Debian 7.7/8/9/10、 Fedora 25/26/27 和 CentOS。虽然你可以下载 Docker CE 二进制文件并安装到桌面 Linux 上，但我建议添加仓库源以便继续获得修补程序和更新。</p><h3 id="在桌面-linux-上安装-docker-ce" tabindex="-1">在桌面 Linux 上安装 Docker CE <a class="header-anchor" href="#在桌面-linux-上安装-docker-ce" aria-label="Permalink to “在桌面 Linux 上安装 Docker CE”">​</a></h3><p>你不需要一个完整的桌面 Linux 来运行 Docker，你也可以将它安装在最小的 Linux 服务器上，即你可以在一个虚拟机中运行。在本教程中，我将在我的主系统的 Fedora 27 和 Ubuntu 17.04 上运行它。</p><h3 id="在-ubuntu-上安装" tabindex="-1">在 Ubuntu 上安装 <a class="header-anchor" href="#在-ubuntu-上安装" aria-label="Permalink to “在 Ubuntu 上安装”">​</a></h3><p>首先，运行系统更新，以便你的 Ubuntu 软件包完全更新：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-get update</span></span></code></pre></div><p>现在运行系统升级：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-get dist-upgrade</span></span></code></pre></div><p>然后安装 Docker PGP 密钥：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo add-apt-repository &quot;deb [arch=amd64] https://download.docker.com/linux/ubuntu $(lsb_release -cs) stable&quot;</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Update the repository info again:</span></span>
<span class="line"><span>$ sudo apt-get update</span></span></code></pre></div><p>现在安装 Docker CE：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-get install docker-ce</span></span></code></pre></div><p>一旦安装完成，Docker CE 就会在基于 Ubuntu 的系统上自动运行，让我们来检查它是否在运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl status docker</span></span></code></pre></div><p>你应该得到以下输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>docker.service - Docker Application Container Engine</span></span>
<span class="line"><span>  Loaded: loaded (/lib/systemd/system/docker.service; enabled; vendor preset: enabled)</span></span>
<span class="line"><span>  Active: active (running) since Thu 2017-12-28 15:06:35 EST; 19min ago</span></span>
<span class="line"><span>    Docs: https://docs.docker.com</span></span>
<span class="line"><span>Main PID: 30539 (dockerd)</span></span></code></pre></div><p>由于 Docker 安装在你的系统上，你现在可以使用 Docker CLI（命令行界面）运行 Docker 命令。像往常一样，我们运行 ‘Hello World’ 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker run hello-world</span></span></code></pre></div><p><img src="https://lh5.googleusercontent.com/YMChR_7xglpYBT91rtXnqQc6R1Hx9qMX_iO99vL8Z8C0-BlynDcL5B5pG-zzH0fKU0Qvnzd89v0KDEbZiO0gTfGNGfDtO-FkTt0bmzIQ-TKbNmv18S9RXdkSeXqgKDFRewnaHPj2" alt="YMChR_7xglpYBT91rtXnqQc6R1Hx9qMX_iO99vL8"></p><p>恭喜！在你的 Ubuntu 系统上正在运行着 Docker。</p><h3 id="在-fedora-上安装-docker-ce" tabindex="-1">在 Fedora 上安装 Docker CE <a class="header-anchor" href="#在-fedora-上安装-docker-ce" aria-label="Permalink to “在 Fedora 上安装 Docker CE”">​</a></h3><p>Fedora 27 上的情况有些不同。在 Fedora 上，你首先需要安装 <code>def-plugins-core</code> 包，这将允许你从 CLI 管理你的 DNF 包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf -y install dnf-plugins-core</span></span></code></pre></div><p>现在在你的系统上安装 Docker 仓库：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf config-manager \\</span></span>
<span class="line"><span>    --add-repo \\</span></span>
<span class="line"><span>    https://download.docker.com/linux/fedora/docker-ce.repo</span></span>
<span class="line"><span>It’s time to install Docker CE:</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install docker-ce</span></span></code></pre></div><p>与 Ubuntu 不同，Docker 不会在 Fedora 上自动启动。那么让我们启动它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl start docker</span></span></code></pre></div><p>你必须在每次重新启动后手动启动 Docker，因此让我们将其配置为在重新启动后自动启动。<code>$ systemctl enable docker</code> 就行。现在该运行 Hello World 命令了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker run hello-world</span></span></code></pre></div><p>恭喜，在你的 Fedora 27 系统上正在运行着 Docker。</p><h3 id="解除-root" tabindex="-1">解除 root <a class="header-anchor" href="#解除-root" aria-label="Permalink to “解除 root”">​</a></h3><p>你可能已经注意到你必须使用 <code>sudo</code> 来运行 <code>docker</code> 命令。这是因为 Docker 守护进程与 UNIX 套接字绑定，而不是 TCP 端口，套接字由 root 用户拥有。所以，你需要 <code>sudo</code> 权限才能运行 <code>docker</code> 命令。你可以将系统用户添加到 docker 组，这样它就不需要 <code>sudo</code> 了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo groupadd docker</span></span></code></pre></div><p>在大多数情况下，在安装 Docker CE 时会自动创建 Docker 用户组，因此你只需将用户添加到该组中即可：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo usermod -aG docker $USER</span></span></code></pre></div><p>为了测试该组是否已经成功添加，根据用户名运行 <code>groups</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ groups swapnil</span></span></code></pre></div><p>（这里，<code>swapnil</code> 是用户名。）</p><p>这是在我系统上的输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>swapnil : swapnil adm cdrom sudo dip plugdev lpadmin sambashare docker</span></span></code></pre></div><p>你可以看到该用户也属于 docker 组。注销系统，这样组就会生效。一旦你再次登录，在不使用 <code>sudo</code> 的情况下试试 Hello World 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ docker run hello-world</span></span></code></pre></div><p>你可以通过运行以下命令来查看关于 Docker 的安装版本以及更多系统信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ docker info</span></span></code></pre></div><h3 id="在-macos-和-windows-上安装-docker-ce" tabindex="-1">在 macOS 和 Windows 上安装 Docker CE <a class="header-anchor" href="#在-macos-和-windows-上安装-docker-ce" aria-label="Permalink to “在 macOS 和 Windows 上安装 Docker CE”">​</a></h3><p>你可以在 macOS 和 Windows 上很轻松地安装 Docker CE（和 EE）。下载官方为 macOS 提供的 Docker 安装包，在 macOS 上安装应用程序的方式是只需将它们拖到 Applications 目录即可。一旦文件被复制，从 spotlight（LCTT 译注：mac 下的搜索功能）下打开 Docker 开始安装。一旦安装，Docker 将自动启动，你可以在 macOS 的顶部看到它。</p><p><img src="https://lh3.googleusercontent.com/IEX23j65zYlF8mZ1c-T_vFw_i1B1T1hibw_AuhEAfwv9oFpMfcAqkgEk7K5o58iDAAfGozSpIvY_qEsTOHRlSbesMKwTnG9rRkWba1KPSmnuH1LyoccDGNO3Clbz8du0gSByZxNj" alt="IEX23j65zYlF8mZ1c-T_vFw_i1B1T1hibw_AuhEA"></p><p>macOS 是类 UNIX 系统，所以你可以简单地打开终端应用程序，并开始使用 Docker 命令。测试 hello world 应用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ docker run hello-world</span></span></code></pre></div><p>恭喜，你已经在你的 macOS 上运行了 Docker。</p><h3 id="在-windows-10-上安装-docker" tabindex="-1">在 Windows 10 上安装 Docker <a class="header-anchor" href="#在-windows-10-上安装-docker" aria-label="Permalink to “在 Windows 10 上安装 Docker”">​</a></h3><p>你需要最新版本的 Windows 10 Pro 或 Server 才能在它上面安装或运行 Docker。如果你没有完全更新，Windows 将不会安装 Docker。我在 Windows 10 系统上遇到了错误，必须运行系统更新。我的版本还很落后，我出现了[这个][14] bug。所以，如果你无法在 Windows 上安装 Docker，只要知道并不是只有你一个。仔细检查该 bug 以找到解决方案。</p><p>一旦你在 Windows 上安装 Docker 后，你可以通过 WSL 使用 bash shell，或者使用 PowerShell 来运行 Docker 命令。让我们在 PowerShell 中测试 “Hello World” 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>PS C:\\Users\\swapnil&gt; docker run hello-world</span></span></code></pre></div><p>恭喜，你已经在 Windows 上运行了 Docker。</p><p>在下一篇文章中，我们将讨论如何从 DockerHub 中拉取镜像并在我们的系统上运行容器。我们还会讨论推送我们自己的容器到 Docker Hub。</p><hr>`,68)),i("p",null,[s[3]||(s[3]=e("via: ",-1)),t(a,{href:"https://www.linux.com/blog/learn/intro-to-linux/how-install-docker-ce-your-desktop"},{default:o(()=>[...s[2]||(s[2]=[e("https://www.linux.com/blog/learn/intro-to-linux/how-install-docker-ce-your-desktop",-1)])]),_:1})]),i("p",null,[s[8]||(s[8]=e("作者：",-1)),t(a,{href:"https://www.linux.com/users/arnieswap"},{default:o(()=>[...s[4]||(s[4]=[e("SWAPNIL BHARTIYA",-1)])]),_:1}),s[9]||(s[9]=e(" 选题：",-1)),t(a,{href:"https://github.com/lujun9972"},{default:o(()=>[...s[5]||(s[5]=[e("lujun9972",-1)])]),_:1}),s[10]||(s[10]=e(" 译者：",-1)),t(a,{href:"https://github.com/MjSeven"},{default:o(()=>[...s[6]||(s[6]=[e("MjSeven",-1)])]),_:1}),s[11]||(s[11]=e(" 校对：",-1)),t(a,{href:"https://github.com/wxy"},{default:o(()=>[...s[7]||(s[7]=[e("wxy",-1)])]),_:1})]),i("p",null,[s[14]||(s[14]=e("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...s[12]||(s[12]=[e("LCTT",-1)])]),_:1}),s[15]||(s[15]=e(" 原创编译，",-1)),t(a,{href:"https://linux.cn/"},{default:o(()=>[...s[13]||(s[13]=[e("Linux中国",-1)])]),_:1}),s[16]||(s[16]=e(" 荣誉推出",-1))])])}const y=l(c,[["render",k]]);export{D as __pageData,y as default};
